extern "C" {
volatile int seed = 3;
int total;
const unsigned char bytes[] = {15, 0, 255};
const unsigned char *pointer = bytes;
__attribute__((noinline)) int twice(int n) { return n * 2; }
int __asm_editor_main(void) {
    int sum = 0;
    for (int i = 0; i < seed; i++) sum += twice(i + 1);
    total = sum;
    return total + pointer[0] + pointer[2];
}
}
